import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Scanner;

public class StudentReport {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.println("===== STUDENT REPORT =====");
        System.out.print("Enter student name: ");
        String studentName = scanner.nextLine();

        System.out.print("Enter marks for Subject 1: ");
        BigDecimal marks1 = new BigDecimal(scanner.nextLine()).setScale(2, RoundingMode.HALF_UP);

        System.out.print("Enter marks for Subject 2: ");
        BigDecimal marks2 = new BigDecimal(scanner.nextLine()).setScale(2, RoundingMode.HALF_UP);

        System.out.print("Enter marks for Subject 3: ");
        BigDecimal marks3 = new BigDecimal(scanner.nextLine()).setScale(2, RoundingMode.HALF_UP);

        BigDecimal totalMarks = marks1.add(marks2).add(marks3);
        BigDecimal averageMarks = totalMarks.divide(BigDecimal.valueOf(3), 2, RoundingMode.HALF_UP);

        System.out.println();
        System.out.println("===== RESULT =====");
        System.out.println("Student: " + studentName);
        System.out.println("Total Marks: " + totalMarks);
        System.out.println("Average: " + averageMarks);

        if (averageMarks.compareTo(new BigDecimal("40")) >= 0) {
            System.out.println("Status: PASS");
        } else {
            System.out.println("Status: FAIL");
        }
    }
}
